new='    /** V0.6.32 - fidélité visuelle aux deux références maîtres. */\n    private fun showCategoryCatalog(video: Boolean) {\n        generation++\n        screenMode = if (video) "videos-catalog" else "images-catalog"\n        route = if (video) Route.VIDEOS else Route.IMAGES\n        videoCategoryTab = video\n        selected.clear()\n        if (video) { showCategoryManager(true, CategoryEntry.VIDEOS); return }\n\n        var cats=savedCategories().toMutableList()\n        if(cats.size<8 || cats.take(8).any{!it.startsWith("Catégorie ")}) {\n            cats=(1..8).map{"Catégorie $it"}.toMutableList()\n            prefs.edit().putString("category_names",cats.joinToString("\\u001f")).apply()\n        }\n\n        val page=LinearLayout(this).apply { orientation=LinearLayout.VERTICAL;setBackgroundColor(black) }\n        page.addView(galleryHeader(false){showHome()},LinearLayout.LayoutParams(-1,dp(205)))\n\n        val body=LinearLayout(this).apply {\n            orientation=LinearLayout.VERTICAL;setPadding(dp(7),dp(4),dp(7),0)\n            background=GradientDrawable().apply{setColor(black);setStroke(dp(1),gold)}\n        }\n        val ident=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}\n        ident.addView(simpleLabel("?",48f,gold).apply{\n            gravity=Gravity.CENTER;background=GradientDrawable().apply{setColor(Color.rgb(13,13,13));setStroke(dp(1),gold)}\n        },LinearLayout.LayoutParams(dp(70),dp(64)).apply{rightMargin=dp(8)})\n        val tx=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL}\n        tx.addView(simpleLabel("Catégorie 1",19f,cream))\n        tx.addView(simpleLabel("0 image",11f,cream))\n        tx.addView(simpleLabel("Apprendre  •  Comprendre  •  Protéger  •  Partager",10f,gold))\n        ident.addView(tx,LinearLayout.LayoutParams(0,-2,1f))\n        ident.addView(action("▰  Changer\\nde catégorie"){showImagesCategories()},LinearLayout.LayoutParams(dp(145),dp(62)))\n        body.addView(ident)\n\n        val tool=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}\n        tool.addView(action("⌕  Rechercher une image…"){openSearch(Route.IMAGES)},LinearLayout.LayoutParams(0,dp(52),1f).apply{rightMargin=dp(5)})\n        tool.addView(action("☷  Filtres"){openFilters()},LinearLayout.LayoutParams(dp(100),dp(52)))\n        val sizes=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}\n        listOf("▦\\nPetites","▦\\nMoyennes","▦\\nGrandes").forEach{sizes.addView(action(it){},LinearLayout.LayoutParams(dp(58),dp(52)))}\n        tool.addView(sizes)\n        body.addView(tool)\n\n        val sort=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}\n        sort.addView(simpleLabel("Trier par :",12f,cream),LinearLayout.LayoutParams(dp(75),dp(42)))\n        listOf("Date ↓","Nom","Type","Taille").forEach{sort.addView(action(it){},LinearLayout.LayoutParams(0,dp(42),1f))}\n        sort.addView(simpleLabel("▧   0 image",11f,cream).apply{gravity=Gravity.CENTER},LinearLayout.LayoutParams(dp(110),dp(42)))\n        body.addView(sort)\n\n        val grid=GridLayout(this).apply{columnCount=3;alignmentMode=GridLayout.ALIGN_BOUNDS}\n        fun glp()=GridLayout.LayoutParams().apply{width=0;height=dp(112);columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(dp(2),dp(2),dp(2),dp(2))}\n        fun tile(title:String,plus:Boolean=false)=LinearLayout(this).apply{\n            orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER\n            background=GradientDrawable().apply{setColor(Color.rgb(11,11,11));setStroke(dp(1),gold)}\n            addView(simpleLabel(if(plus)"+" else "?",if(plus)48f else 42f,if(plus)gold else cream).apply{gravity=Gravity.CENTER},LinearLayout.LayoutParams(-1,dp(62)))\n            addView(simpleLabel(title,12f,cream).apply{gravity=Gravity.CENTER},LinearLayout.LayoutParams(-1,dp(27)))\n            if(!plus)addView(simpleLabel("0 image",9f,cream).apply{gravity=Gravity.CENTER},LinearLayout.LayoutParams(-1,dp(18)))\n            setOnClickListener{if(plus)addCategoryDialog() else openGalleryCategory(title,Route.IMAGES)}\n        }\n        grid.addView(tile("Nouvelle\\ncatégorie",true),glp())\n        cats.take(8).forEach{grid.addView(tile(it),glp())}\n        body.addView(ScrollView(this).apply{addView(grid,FrameLayout.LayoutParams(-1,-2))},LinearLayout.LayoutParams(-1,0,1f))\n        page.addView(body,LinearLayout.LayoutParams(-1,0,1f))\n\n        val actions=LinearLayout(this).apply{\n            orientation=LinearLayout.VERTICAL;setPadding(dp(7),dp(3),dp(7),dp(3))\n            background=GradientDrawable().apply{setColor(black);setStroke(dp(1),gold)}\n        }\n        val a=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}\n        listOf("ⓧ  0 image\\nsélectionnée","Partager\\nChatGPT","Partager\\nInstagram","Partager\\nFacebook","Plus de\\npartages").forEach{a.addView(action(it){},LinearLayout.LayoutParams(0,dp(50),1f))}\n        actions.addView(a)\n        val b=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}\n        b.addView(action("▰  Déplacer\\n(0 / 1000)"){},LinearLayout.LayoutParams(0,dp(50),1f))\n        b.addView(action("▧  Envoyer à la galerie\\n(0 / 1000)"){},LinearLayout.LayoutParams(0,dp(50),1.2f))\n        b.addView(dangerAction("Supprimer\\n(0 / 100 max)"){},LinearLayout.LayoutParams(0,dp(50),1f))\n        b.addView(action("☑  Tout sélectionner"){},LinearLayout.LayoutParams(0,dp(50),1.15f))\n        actions.addView(b)\n        page.addView(actions)\n        page.addView(navBar(Route.IMAGES),LinearLayout.LayoutParams(-1,dp(76)))\n        setContentView(page)\n    }\n\n'
